fn main() {
    let a = String::from("hello");
    let b = a;
    println!("{a}");
    println!("{b}");
}

fn main() {
    let a = 5;
    let b = a;
    println!("{a} {b}");
}

fn shout(s: &str) -> String {
    s.to_uppercase()
}

fn main() {
    let greeting = String::from("hello");
    let loud = shout(&greeting);
    println!("{greeting} -> {loud}");
}

fn consume(s: String) -> usize {
    s.len()
}

fn main() {
    let s = String::from("hi");
    let n = consume(s);
    println!("{n} {s}");
}

fn consume(s: String) -> usize {
    s.len()
}

fn main() {
    let s = String::from("hi");
    let n = consume(s.clone());
    println!("{n} {s}");
}
